# Converted to the revised ten-section template (plus section 11); content and tables carried from the previous version.
BOOK = 'Jeremiah'
TESTAMENT = 'Old Testament'
GENRE = 'prophets'
SUBTITLE = 'Judgment on Judah, the Weeping Prophet, and the New Covenant Promised'
SECTIONS = [(1, 'Book Setting & Program Identity', [('p', 'This section introduces you to the book by explaining who wrote it, who received it, and what was happening when it was written. It also shows you which of God’s programs the book belongs to — Israel’s prophetic program or the Body of Christ’s mystery program. Knowing the setting and the program identity helps you read the book in its proper context and understand how its teachings fit into the larger story of Scripture.'), ('p', 'Jeremiah records the word of the LORD to the prophet ordained “a prophet unto the nations” (Jer. 1:5) and sent to Judah and Jerusalem. It follows his call, his warnings and laments, the siege and fall of Jerusalem, and the promises of restoration, the Branch of David and the new covenant (Jer. 1:10; 23:5; 30:3; 31:31–34; 33:15).'), ('box', 'Program Identity:', 'This book belongs entirely to the Prophecy Program, where the LORD speaks to the house of Israel and the house of Judah about judgment, exile and a restoration with a new covenant made with them (Jer. 7:23; 30:3; 31:31).')]),
(2, 'Narrative Flow of Jeremiah', [('p', 'This section gives you a simple walkthrough of how the book unfolds. Instead of diving into details right away, it shows the major movements in the book — how its message begins, how it develops, and how it builds toward its close. Seeing the flow of the book helps you understand the big picture before you study the individual passages.'), ('h3', 'Movement 1 — The Call and the Warnings (Chs. 1–25)'), ('p', 'Jeremiah is called, warns Judah from the temple gate, and speaks of the heart, the potter and the false shepherds (Jer. 1:5, 10; 7:23; 17:9–10; 23:5).'), ('h3', 'Movement 2 — Conflict and Exile (Chs. 26–29)'), ('p', 'False prophets are answered, and the exiles in Babylon are told to seek the LORD (Jer. 29:11, 13).'), ('h3', 'Movement 3 — The Book of Consolation (Chs. 30–33)'), ('p', 'The LORD promises to bring again the captivity, to make a new covenant, and to cause the Branch of righteousness to grow up unto David (Jer. 30:3; 31:3, 31–36; 32:37; 33:15, 20–21).'), ('h3', 'Movement 4 — The Fall of Jerusalem (Chs. 34–45)'), ('p', 'The city falls, and Jeremiah is carried down to Egypt (Jer. 32:17; 34–45).'), ('h3', 'Movement 5 — Oracles on the Nations (Chs. 46–52)'), ('p', 'The LORD speaks over the nations and against Babylon, and the book closes with the fall of Jerusalem (Jer. 10:10; 46–52).')]),
(3, 'Program Themes in Jeremiah', [('p', 'This section highlights the major ideas emphasized in the book — the big doctrinal themes that shape how Israel should think and live under the covenants. These themes are not verse-by-verse explanations; they are the book’s main emphases, the repeated ideas God wants Israel to carry forward. Seeing these themes together helps you understand the book’s message before you look at the individual truths in the tables.'), ('ol', ['<b>A Prophet to the Nations</b> — “Before I formed thee in the belly I knew thee… I ordained thee a prophet unto the nations” (Jer. 1:5).', '<b>Obey and Be His People</b> — “Obey my voice, and I will be your God, and ye shall be my people” (Jer. 7:23).', '<b>The Heart</b> — “The heart is deceitful above all things, and desperately wicked: who can know it?” (Jer. 17:9).', '<b>The Righteous Branch</b> — “I will raise unto David a righteous Branch” (Jer. 23:5).', '<b>The Captivity Returned</b> — “I will bring again the captivity of my people Israel and Judah” (Jer. 30:3).', '<b>The New Covenant</b> — “I will make a new covenant with the house of Israel, and with the house of Judah” (Jer. 31:31).', '<b>The Covenant That Holds</b> — “If those ordinances depart from before me, saith the LORD, then the seed of Israel also shall cease from being a nation before me for ever” (Jer. 31:36).'])]),
(4, 'Christ in Jeremiah', [('p', 'This section gathers what the book teaches about Christ — through foreshadowing, typology, and prophetic anticipation. These statements help you see the book’s Christ-centered trajectory before you study the doctrinal truths in detail. By collecting these points together, you get a clear picture of how Jeremiah points to Christ.'), ('ol', ['<b>The Righteous Branch</b> — The Branch raised to David is reported as written (Jer. 23:5; 33:15).', '<b>The New Covenant</b> — The passage is quoted in the letter to the Hebrews (Jer. 31:31–34; Heb. 8:8–12). It is made with the house of Israel and the house of Judah (Jer. 31:31).', '<b>The Weeping Prophet</b> — Jeremiah’s laments over the people are reported as written (Jer. 8:20; 9:1).'])]),
(5, 'Israel, the Law, and the Covenants in Jeremiah', [('p', 'This section helps you see how Jeremiah speaks about Israel, the law, and the covenants without mixing programs. Jeremiah operates within Israel’s prophetic framework. By gathering these points together, this section shows you how to read Jeremiah in its own setting — as an Israel-program book — while recognizing what it says (and does not say) about the Body of Christ.'), ('p', 'Jeremiah reinforces Israel’s:'), ('ul', ['covenant, land and exile of Judah (Jer. 30:3; 32:37)', 'the house of Israel and the house of Judah as the covenant parties (Jer. 31:31)', 'David’s Branch and throne (Jer. 23:5; 33:15, 21)', 'the LORD’s everlasting love for Israel (Jer. 31:3)']), ('p', 'All content belongs exclusively to the Prophecy Program.')]),
(6, 'Israel-Program Distinctions', [('p', 'This section highlights the teachings in Jeremiah that belong uniquely to Israel’s prophetic program — truths rooted in prophecy, covenant promises, national identity, and God’s dealings with Israel. By gathering these together, this section helps you see how Jeremiah contributes to Israel’s story without borrowing from the Body-of-Christ program.'), ('ul', ['Obey and Be His People — “I will be your God, and ye shall be my people.” (Jer. 7:23).', 'The Righteous Branch — “I will raise unto David a righteous Branch.” (Jer. 23:5).', 'Thoughts of Peace — “thoughts of peace, and not of evil, to give you an expected end.” (Jer. 29:11).', 'The Captivity Returned — “I will bring again the captivity of my people Israel and Judah.” (Jer. 30:3).', 'Everlasting Love — “I have loved thee with an everlasting love.” (Jer. 31:3).', 'The New Covenant — “I will make a new covenant with the house of Israel, and with the house of Judah.” (Jer. 31:31).', 'The Law Within — “I will put my law in their inward parts.” (Jer. 31:33).', 'Israel Remains a Nation — “the seed of Israel also shall cease from being a nation before me for ever.” (Jer. 31:36).', 'The Gathering — “I will gather them out of all countries.” (Jer. 32:37).', 'The Branch of Righteousness — “cause the Branch of righteousness to grow up unto David.” (Jer. 33:15).', 'The Covenant With David — “my covenant be broken with David my servant.” (Jer. 33:21).'])]),
(7, 'Truths Table: What Jeremiah Says', [('p', 'This table gathers the key statements, instructions, and teachings in Jeremiah and shows which ones belong to Israel’s prophetic program. Each row lists a truth from the book, explains what it says, and identifies its program identity based on Israel’s covenant setting. This helps you see, at a glance, what Jeremiah teaches directly to Israel and keeps those truths separate from universal principles that apply more broadly.'), ('table', ['Category', 'Truth Revealed in Jeremiah', 'Program Identity', 'Scripture'], [['Obey and Be His People', '“I will be your God, and ye shall be my people.”', 'Israel / Kingdom / Prophecy Explicit Truth', 'Jer. 7:23'], ['The Righteous Branch', '“I will raise unto David a righteous Branch.”', 'Israel / Kingdom / Prophecy Explicit Truth', 'Jer. 23:5'], ['Thoughts of Peace', '“thoughts of peace, and not of evil, to give you an expected end.”', 'Israel / Kingdom / Prophecy Explicit Truth', 'Jer. 29:11'], ['The Captivity Returned', '“I will bring again the captivity of my people Israel and Judah.”', 'Israel / Kingdom / Prophecy Explicit Truth', 'Jer. 30:3'], ['Everlasting Love', '“I have loved thee with an everlasting love.”', 'Israel / Kingdom / Prophecy Explicit Truth', 'Jer. 31:3'], ['The New Covenant', '“I will make a new covenant with the house of Israel, and with the house of Judah.”', 'Israel / Kingdom / Prophecy Explicit Truth', 'Jer. 31:31'], ['The Law Within', '“I will put my law in their inward parts.”', 'Israel / Kingdom / Prophecy Explicit Truth', 'Jer. 31:33'], ['Israel Remains a Nation', '“the seed of Israel also shall cease from being a nation before me for ever.”', 'Israel / Kingdom / Prophecy Explicit Truth', 'Jer. 31:36'], ['The Gathering', '“I will gather them out of all countries.”', 'Israel / Kingdom / Prophecy Explicit Truth', 'Jer. 32:37'], ['The Branch of Righteousness', '“cause the Branch of righteousness to grow up unto David.”', 'Israel / Kingdom / Prophecy Explicit Truth', 'Jer. 33:15'], ['The Covenant With David', '“my covenant be broken with David my servant.”', 'Israel / Kingdom / Prophecy Explicit Truth', 'Jer. 33:21']], [20, 34, 26, 20])]),
(8, 'Universal Truths Table (All People, All Time)', [('p', 'This table gathers the truths in Jeremiah that apply to everyone, not just Israel. These are principles rooted in God’s character — things that hold true across all programs and all ages. By separating these universal truths from Israel’s covenant-specific instructions, this section helps you see what Jeremiah teaches all believers everywhere and what it teaches Israel in its own setting.'), ('table', ['Universal Truth', 'Description', 'Scripture'], [['Glorying in the LORD', '“let him that glorieth glory in this, that he understandeth and knoweth me.”', 'Jer. 9:24'], ['The True God', '“the LORD is the true God, he is the living God, and an everlasting king.”', 'Jer. 10:10'], ['The Heart', '“The heart is deceitful above all things, and desperately wicked: who can know it?”', 'Jer. 17:9'], ['He Searches the Heart', '“I the LORD search the heart, I try the reins.”', 'Jer. 17:10'], ['Nothing Too Hard', '“there is nothing too hard for thee.”', 'Jer. 32:17']], [28, 48, 24])]),
(9, 'Program-Safe Application Grid', [('p', 'This section shows how to apply the teachings of Jeremiah without mixing programs. The applications come from Israel’s covenant story and from universal truths that apply to everyone. By keeping the applications tied to what the book actually says — and not borrowing commands from Israel’s covenants for the Body of Christ — this grid helps you respond to Jeremiah in a way that is faithful to its setting, clear, and safe.'), ('ol', ['<b>Glory only in knowing Him</b> — Understanding and knowing the LORD (Jer. 9:24).', '<b>Worship the living God</b> — The true God and everlasting king (Jer. 10:10).', '<b>Distrust the heart</b> — It is deceitful above all things (Jer. 17:9).', '<b>Welcome His searching</b> — He tries the reins (Jer. 17:10).', '<b>Trust His power</b> — Nothing is too hard for Him (Jer. 32:17).'])]),
(10, 'Teaching Outline for Jeremiah', [('p', 'This outline gives you a teacher-ready structure for presenting the book. It follows the narrative movements and highlights the major themes, making it easy to teach Jeremiah in classes, small groups, or personal study.'), ('olr', ['The Call and the Warnings (Chs. 1–25) — Sent to Judah. <i>(Jer. 1:5; 7:23; 17:9–10; 23:5)</i>', 'Conflict and Exile (Chs. 26–29) — The word to the exiles. <i>(Jer. 29:11)</i>', 'The Book of Consolation (Chs. 30–33) — Return, Branch and new covenant. <i>(Jer. 30:3; 31:31–36; 33:15)</i>', 'The Fall of Jerusalem (Chs. 34–45) — Nothing too hard. <i>(Jer. 32:17)</i>', 'Oracles on the Nations (Chs. 46–52) — The true God. <i>(Jer. 10:10)</i>'])]),
(11, 'Companion Usage and Study Suggestions', [('h3', 'How to Use This Companion in Personal Study'), ('p', 'This Companion is designed to walk alongside you as you read Jeremiah, helping you see both the prophetic structure of the book and the timeless truths rooted in God’s character. Use it slowly, chapter by chapter, letting the narrative movements, themes, and universal truths deepen your understanding. The Program-Safe Applications will guide your heart toward sober self-examination, trust, and reverence for the LORD without confusing Israel’s covenant commands with the Body of Christ’s calling today.'), ('h3', 'How to Use This Companion in Small Groups or Classes'), ('p', 'This Companion provides a clear, structured framework that makes teaching Jeremiah simple and accessible. Each section gives you ready-to-use material: narrative movements for overview, prophecy-program themes for doctrinal clarity, universal truths for discussion, and a pastoral teaching outline for weekly lessons. Use the tables to help your group distinguish Israel’s covenant identity from universal principles, and use the Program-Safe Application Grid to foster meaningful, Christ-centered conversation.'), ('h3', 'How This Companion Fits Within the Acts Overlap Theology Series'), ('p', 'This Companion is part of a larger series designed to help believers read every book of Scripture without blurring God’s prophetic program for Israel and His mystery program for the Body of Christ. Within the Acts Overlap Theology Series, Jeremiah stands firmly in Israel’s covenant story, yet it still reveals universal truths that shape Christian character today. This Companion shows you how to honor the book’s prophetic context while drawing out the timeless principles that apply to all believers in every age.')])]

# Place in God's Storyline (Master Standard v1.155): last item of Section 1
from storyline import S as _STORY
SECTIONS[0][2].append(('p', '<b>Place in God’s Storyline.</b> ' + _STORY['jeremiah'][1]))
